final _log = Logger('dsrp.User');

/// Verification key generated by user on client-side.
/// This data should be registered with the server for future authentication.
class SaltedVerificationKey {
  //OPTIMIZE: Use Uint8List, since int defaults 64-bit rather than a byte?
  final List<int> key;
  final List<int> salt;

  SaltedVerificationKey({required this.key, required this.salt});
}

/// Data to be sent to the server to verify the user session key.
class UserSessionVerifiers {
  final String userId;
  final List<int> ephemeralUserPublicKey;
  final List<int> sessionKeyVerifier;

  UserSessionVerifiers({
      required this.userId,
      required this.ephemeralUserPublicKey,
      required this.sessionKeyVerifier
  });
}

/// Operations the user / client performs to authenticate with a server via SRP.
///
/// Designed to mimic the API of Python's pysrp library.
class User {

  /// User identifier.
  final String userId;
  /// User password.
  final String password;
  final HashAlgorithmChoice hashAlgorithm;
  /// Hash algorithm used during SRP key and verifier calculations (e.g., SHA256).
  final HashAlgorithm _hashAlgorithm;
  /// A generator modulo N.
  /// Typically denoted 'g'.
  final BigInt generator;
  /// A large, safe prime.
  /// Typically denoted 'N'.
  /// By definition a safe prime N = 2q + 1, where q is a Sophie Germain prime.
  /// All arithmetic is performed in the field of integers modulo N.
  /// TODO: Generate N.
  final BigInt safePrime;

  // final List<int> _ephemeralServerPublicKey;
  final List<int> _verifierKeySalt;

  /// Shared symmetric key used for encrypting messages sent between user and server.
  ///
  /// Derived from the Diffie-Hellman shared secret.
  late final List<int> sessionKey;
  /// To be sent to the server so it can verify the user and the user's derived
  /// session key.
  late final List<int> _userSessionKeyVerifier;

  /// Ephemeral asymmetric private key generated by user during authentication and then discarded.
  BigInt? _ephemeralUserPrivateKey;
  /// Ephemeral asymmetric public key generated by user during authentication and then discarded.
  List<int>? _ephemeralUserPublicKeyBytes;

  /// [challenge] is provided by server as part of initial user login handshake.
  static Future<User> fromUserCredsAndChallenge({
    required String userId,
    required String password,
    required Challenge challenge,
    final List<int>? ephemeralUserPrivateKey,
  }) async {
    final user = User._(
      userId: userId, password: password,
      generator: BigInt.from(challenge.generator),
      safePrime: challenge.safePrime.toBigInt(),
      verifierKeySalt: challenge.verifierKeySalt,
      hashAlgorithm: challenge.hashAlgorithm,
    );
    user._generateEphemeralUserAsymmetricKeys(
      ephemeralUserPrivateKeyBytes: ephemeralUserPrivateKey);
    // Derives session key and its user-side verifier M1.
    await user._processChallenge(challenge);
    return user;
  }

  User._({
    required this.userId,
    required this.password,
    required this.generator,
    required this.safePrime,
    required List<int> verifierKeySalt,
    required this.hashAlgorithm,
  }): _verifierKeySalt = verifierKeySalt,
    _hashAlgorithm = getHashAlgorithm(hashAlgorithm);

  // _verifierKeySalt = challenge.verifierKeySalt
  // {
  //   // if (serverChallenge != null) {
  //     // generator = BigInt.from(serverChallenge.generator);
  //     // safePrime = serverChallenge.safePrime.toBigInt();
  //     // hashAlgorithm =
  //   // } else {
  //     // this.generator = generator != null ? BigInt.from(generator) : defaultGenerator;
  //     // this.safePrime = safePrime != null ? safePrime.toBigInt() : defaultSafePrime;
  //     //FIXME: Should this be provided in server challenge?
  //     // hashAlgorithm = hashAlgorithm ?? defaultHashAlgorithm;
  //   // }

  // }

  /// Creates salted verification key.
  ///
  /// Pass this data to server as part of user registration request.
  static Future<SaltedVerificationKey> createSaltedVerificationKey({
      required String userId, required String password,
      int? generator, List<int>? safePrime,
      HashAlgorithmChoice? hashAlgorithm,
      List<int>? salt
  }) async {
    final generatorBigInt = generator != null ? BigInt.from(generator) : defaultGenerator;
    final safePrimeBigInt = safePrime?.toBigInt() ?? defaultSafePrime;
    if (safePrime == null) {
      _log.warning('Using default safe prime. For production use, generate a custom safe prime using scripts/generate_safe_primes to reduce risk of pre-computed attacks.');
    }
    final chosenHashAlgorithm = getHashAlgorithm(hashAlgorithm ?? defaultHashAlgorithmChoice);
    salt ??= generateRandomBytes(defaultSaltByteLengthForSaltedVerificationKey);

    final privateKey = await _derivePrivateKey(userId: userId, password: password,
      salt: salt, hashAlgorithm: chosenHashAlgorithm);
    final verifierKey = _deriveVerificationKey(privateKey: privateKey,
      generator: generatorBigInt, safePrime: safePrimeBigInt);
    final verifierKeyBytes = verifierKey.toByteList();
    return SaltedVerificationKey(
      key: verifierKeyBytes,
      salt: salt,
    );
  }

  //TODO: Add support for the Argon2 hash algorithm.
  // Future<SaltedVerificationKey> createSaltedVerificationKeyWithArgon2() async {
  //   //TODO: How big should the salt be?
  //   final salt = List<int>.generate(128, (index) => random.nextInt(256));
  //   //TODO: Hash alg should be specifiable.
  //   final argon2id = Argon2id(
