  /// Generates ephemeral user public and private keys which are used only
  /// during SRP login and then discarded.
  _generateEphemeralUserAsymmetricKeys({List<int>? ephemeralUserPrivateKeyBytes}) {
    //TODO: How big should private user and server keys be?
    ephemeralUserPrivateKeyBytes ??= generateRandomBytes(defaultByteLengthForEphemeralKeys);
    _ephemeralUserPrivateKey = ephemeralUserPrivateKeyBytes.toBigInt();
    // A = g^a
    final publicKey = generator.modPow(_ephemeralUserPrivateKey!, safePrime);
    _ephemeralUserPublicKeyBytes = publicKey.toByteList();
  }

  /// Processes challenge from server, deriving session key and its verifier.
  ///
  /// Session key verifier is often denoted 'M' or 'M1'.
  Future<void> _processChallenge(Challenge challenge) async {
    sessionKey = await _deriveSessionKey(challenge.verifierKeySalt, challenge.ephemeralServerPublicKey);
    // H(N)
    final hashedSafePrime = (
      await _hashAlgorithm.hash(safePrime.toByteList())
    ).bytes.toBigInt();
    // H(g)
    final hashedGenerator = (
      await _hashRfc5054([generator.toByteList()])
    ).toBigInt();
    // H(I)
    final hashedUserId = (await _hashAlgorithm.hash(utf8.encode(userId))).bytes;
    // H(N) xor H(g)
    final hashedSafePrimeAndGenerator = (hashedSafePrime ^ hashedGenerator).toByteList();
    // M1 = H(H(N) xor H(g), H(I), s, A, B, K)
    _userSessionKeyVerifier = (await _hashAlgorithm.hash(
        hashedSafePrimeAndGenerator +
        hashedUserId +
        challenge.verifierKeySalt +
        _ephemeralUserPublicKeyBytes! +
        challenge.ephemeralServerPublicKey +
        sessionKey
    )).bytes;
  }

  /// Retrieve user session verifiers to send to server.
  UserSessionVerifiers getUserSessionVerifiers() {
    return UserSessionVerifiers(
      userId: userId,
      ephemeralUserPublicKey: _ephemeralUserPublicKeyBytes!,
      sessionKeyVerifier: _userSessionKeyVerifier,
    );
  }

  /// Verify server session key matches expected value, which verifies server is who is expected.
  /// Throws exception if it does not, in which case authentication should be abandoned.
  ///
  /// Server session key verifier is often denoted 'M2' and is provided in the
  /// server response to the client-generated session key verifier M1.
  Future<void> verifySession(List<int> serverSessionKeyVerifier) async {
    // M2 = H(A, M, K)
    final expectedServerSessionKeyVerifier = (await _hashAlgorithm.hash(
        _ephemeralUserPublicKeyBytes! + _userSessionKeyVerifier + sessionKey
    )).bytes;
    if (!serverSessionKeyVerifier.equals(expectedServerSessionKeyVerifier)) {
      throw AuthenticationFailure('Server session key failed verification.');
    }
  }

  /// Private key (as defined by RFC 5054).
  /// x = H(s, H( I | ‘:’ | p ))
  static Future<BigInt> _derivePrivateKey({
      required String userId, required String password,
      required List<int> salt, required HashAlgorithm hashAlgorithm
  }) async {
    var privateKeyHash = await hashAlgorithm.hash(
        //TODO: How should this be formatted?
        utf8.encode('$userId:$password'));
    privateKeyHash = await hashAlgorithm.hash(salt + privateKeyHash.bytes);
    final privateKey = privateKeyHash.bytes.toBigInt();
    return privateKey;
  }

  /// Password verifier, a.k.a. verification key.
  /// v = g^x
  static BigInt _deriveVerificationKey({
      required BigInt privateKey,
      required BigInt generator, required BigInt safePrime,
  }) {
    final saltedVerificationKey = generator.modPow(privateKey, safePrime);
    return saltedVerificationKey;
  }

  /// Calculates the session key which will later be used for encrypted communication with server.
  ///
  /// K = H( (B - kg^x) ^ (a + ux) ) = H( (B - kv) ^ (a + ux) )
  Future<List<int>> _deriveSessionKey(
      List<int> salt, List<int> serverPublicKeyBytes) async {
    // x
    final privateKey = await _derivePrivateKey(
      userId: userId, password: password,
      salt: _verifierKeySalt,
      hashAlgorithm: _hashAlgorithm,
    );
    // v = g^x
    final verifierKey = _deriveVerificationKey(
      privateKey: privateKey,
      generator: generator, safePrime: safePrime
    );
    // u = H(A,B)
    final randomScramblingParameter = (await _hashRfc5054(
        [_ephemeralUserPublicKeyBytes!, serverPublicKeyBytes]
    )).toBigInt();
    if (randomScramblingParameter == BigInt.zero) {
      throw 'Abort authentication! Random scrambling parameter (u = H(A,B)) is zero.';
    }
    // k = H(N,g)
    final multiplierParameter = (await _hashRfc5054(
        [safePrime.toByteList(), generator.toByteList()]
    )).toBigInt();
    // Notated 'B'.
    final serverPublicKey = serverPublicKeyBytes.toBigInt();
    if (serverPublicKey % safePrime == BigInt.zero) {
      throw 'Abort authentication! Ephemeral public server key is invalid (B % N == 0).';
    }
    // B - k(g^x) = B - kv
    final firstTerm = serverPublicKey - multiplierParameter * verifierKey;
    // a + ux
    final secondTerm = _ephemeralUserPrivateKey! + randomScramblingParameter * privateKey;
    // S = (B - kv) ^ (a + ux)
    final secret = firstTerm.modPow(secondTerm, safePrime);
    // K = H( (B - kg^x) ^ (a + ux) ) = H( (B - kv) ^ (a + ux) ) = H(S)
    final sessionKey = (await _hashAlgorithm.hash(secret.toByteList())).bytes;
    return sessionKey;
  }

  Future<List<int>> _hashRfc5054(List<List<int>> byteLists) async {
    //OPTIMIZE: Make this a class field.
    final safePrimeBytes = safePrime.toByteList();
    return hashRfc5054(
      byteLists: byteLists,
      safePrime: safePrimeBytes,
      hashAlgorithm: _hashAlgorithm
    );
  }
}
